cat > flags.go <<'EOF'
package main

import (
 "fmt"
 "strconv"
 "strings"
)

type FlagSpec struct {
 Name string
 Short byte
 IsBool bool
 Desc string
}
var specs = []FlagSpec{
 {"all", 'a', true, "Search among all cheatpaths"},
 {"brief", 'b', true, "List cheatsheets without file paths"},
 {"colorize", 'c', true, "Colorize output"},
 {"completion", 0, false, "Generate shell completion script (`shell`: bash, zsh, fish, powershell)"},
 {"conf", 0, true, "Display the config file path"},
 {"directories", 'd', true, "List cheatsheet directories"},
 {"edit", 'e', false, "Edit `cheatsheet`"},
 {"help", 'h', true, "help for cheat"},
 {"init", 0, true, "Write a default config file to stdout"},
 {"list", 'l', true, "List cheatsheets"},
 {"path", 'p', false, "Return only sheets found on cheatpath `name`"},
 {"regex", 'r', true, "Treat search <phrase> as a regex"},
 {"rm", 0, false, "Remove (delete) `cheatsheet`"},
 {"search", 's', false, "Search cheatsheets for `phrase`"},
 {"tag", 't', false, "Return only sheets matching `tag`"},
 {"tags", 'T', true, "List all tags in use"},
 {"update", 'u', true, "Update git-backed cheatpaths"},
 {"version", 'v', true, "Print the version number"},
}
type Flags struct {
 Value map[string]string
 Changed map[string]bool
 Args []string
}
func newFlags() *Flags { return &Flags{Value:map[string]string{}, Changed:map[string]bool{}} }
func (f *Flags) B(k string) bool { return f.Value[k]=="true" }
func (f *Flags) S(k string) string { return f.Value[k] }
func longSpec(name string) *FlagSpec { for i:=range specs { if specs[i].Name==name {return &specs[i]} }; return nil }
func shortSpec(ch byte) *FlagSpec { for i:=range specs { if specs[i].Short==ch && ch!=0 {return &specs[i]} }; return nil }
func (f *Flags) set(s *FlagSpec, val string) error {
 if s.IsBool {
  b, err:=strconv.ParseBool(val)
  if err!=nil {
   label:="--"+s.Name
   if s.Short!=0 {label=fmt.Sprintf("-%c, --%s",s.Short,s.Name)}
   return fmt.Errorf("invalid argument %q for %q flag: %s",val,label,err)
  }
  val=strconv.FormatBool(b)
 }
 f.Value[s.Name]=val;f.Changed[s.Name]=true
 return nil
}
func parseFlags(args []string) (*Flags,error) {
 f:=newFlags()
 for i:=0;i<len(args);i++ {
  arg:=args[i]
  if arg=="--" { f.Args=append(f.Args,args[i+1:]...); break }
  if len(arg)<2 || arg[0]!='-' {f.Args=append(f.Args,arg);continue}
  if strings.HasPrefix(arg,"--") {
   text:=arg[2:]
   if text=="" || text[0]=='-' || text[0]=='=' {return f,fmt.Errorf("bad flag syntax: %s",arg)}
   name,val,eq:=strings.Cut(text,"=")
   s:=longSpec(name)
   if s==nil {return f,fmt.Errorf("unknown flag: --%s",name)}
   if !eq {
    if s.IsBool {val="true"} else {
     if i+1>=len(args) {return f,fmt.Errorf("flag needs an argument: --%s",name)}
     i++;val=args[i]
    }
   }
   if err:=f.set(s,val);err!=nil{return f,err}
  } else {
   text:=arg[1:]
   for len(text)>0 {
    ch:=text[0];s:=shortSpec(ch)
    if s==nil {return f,fmt.Errorf("unknown shorthand flag: '%c' in -%s",ch,text)}
    rest:=text[1:];val:="true"
    if strings.HasPrefix(rest,"=") {val=rest[1:];rest=""} else if !s.IsBool {
     if rest!="" {val=rest;rest=""} else {
      if i+1>=len(args) {return f,fmt.Errorf("flag needs an argument: '%c' in -%s",ch,text)}
      i++;val=args[i]
     }
    }
    if err:=f.set(s,val);err!=nil {return f,err};text=rest
   }
  }
 }
 return f,nil
}
EOF
cat > yaml.go <<'EOF'
package main

// A small YAML document reader. It retains scalar spelling and source line
// numbers because both matter to configuration diagnostics and string tags.
import (
 "fmt"
 "strconv"
 "strings"
 "unicode/utf8"
)

type YPair struct { Key string; Value *YNode; Line int }
type YNode struct { Kind string; Text string; Line int; Pairs []YPair; Items []*YNode }
type YLine struct { Text string; Indent int; Num int }
type YParser struct { Lines []YLine; At int; Anchors map[string]*YNode; Duplicates []string }
func ynil(line int) *YNode { return &YNode{Kind:"null",Line:line} }
func stripYComment(s string) string {
 quote:=byte(0);esc:=false
 for i:=0;i<len(s);i++ { c:=s[i]
  if esc {esc=false;continue}
  if quote=='"' && c=='\\' {esc=true;continue}
  if quote!=0 {if c==quote {if quote=='\''&&i+1<len(s)&&s[i+1]=='\'' {i++;continue};quote=0};continue}
  if c=='"'||c=='\'' {quote=c;continue}
  if c=='#' && (i==0 || s[i-1]==' ' || s[i-1]=='\t') {return strings.TrimRight(s[:i]," \t\r")}
 }
 return strings.TrimRight(s," \t\r")
}
func yColon(s string) int {
 quote:=byte(0);depth:=0;esc:=false
 for i:=0;i<len(s);i++ {c:=s[i]
  if esc {esc=false;continue};if quote=='"'&&c=='\\' {esc=true;continue}
  if quote!=0 {if c==quote {quote=0};continue}
  if c=='\''||c=='"' {quote=c;continue}
  if c=='['||c=='{' {depth++};if c==']'||c=='}' {depth--}
  if c==':'&&depth==0&&(i+1==len(s)||s[i+1]==' '||s[i+1]=='\t') {return i}
 }
 return -1
}
func parseYAML(data string) (*YNode,error) {
 if !utf8.ValidString(data) {return nil,fmt.Errorf("yaml: invalid leading UTF-8 octet")}
 p:=&YParser{Anchors:map[string]*YNode{}}
 raw:=strings.Split(strings.ReplaceAll(strings.TrimPrefix(data,"\ufeff"),"\r\n","\n"),"\n")
 started:=false
 for i,s:=range raw {
  if strings.IndexByte(s,0)>=0 {return nil,fmt.Errorf("yaml: control characters are not allowed")}
  n:=0;for n<len(s)&&s[n]==' ' {n++}
  if n<len(s)&&s[n]=='\t' {return nil,fmt.Errorf("yaml: line %d: found character that cannot start any token",i+1)}
  s=stripYComment(s[n:])
  if s=="" {p.Lines=append(p.Lines,YLine{"",n,i+1});continue}
  if n==0 && (s=="---"||s=="...") {
   if started || s=="..." {break};started=true;continue
  }
  if strings.HasPrefix(s,"%") {continue}
  started=true;p.Lines=append(p.Lines,YLine{s,n,i+1})
 }
 p.skip()
 if p.At>=len(p.Lines) {return ynil(1),nil}
 node,err:=p.block(p.Lines[p.At].Indent)
 if err!=nil{return nil,err}
 p.skip()
 if p.At<len(p.Lines) {return nil,fmt.Errorf("yaml: line %d: did not find expected key",p.Lines[p.At].Num)}
 if len(p.Duplicates)>0 {return nil,fmt.Errorf("yaml: unmarshal errors:\n  %s",strings.Join(p.Duplicates,"\n  "))}
 return node,nil
}
func (p *YParser) skip() {for p.At<len(p.Lines)&&p.Lines[p.At].Text=="" {p.At++}}
func isYSeq(s string) bool {return s=="-"||strings.HasPrefix(s,"- ")||strings.HasPrefix(s,"-\t")}
func (p *YParser) addPair(n *YNode, k string, v *YNode, line int) {
 for _,old:=range n.Pairs {if old.Key==k {p.Duplicates=append(p.Duplicates,fmt.Sprintf("line %d: mapping key %q already defined at line %d",line,k,old.Line));break}}
 n.Pairs=append(n.Pairs,YPair{k,v,line})
}
func (p *YParser) block(indent int) (*YNode,error) {
 p.skip();if p.At>=len(p.Lines) {return ynil(1),nil}
 line:=p.Lines[p.At]
 if isYSeq(line.Text) && line.Indent==indent {
  n:=&YNode{Kind:"seq",Line:line.Num}
  for {
   p.skip();if p.At>=len(p.Lines) {break};l:=p.Lines[p.At]
   if l.Indent!=indent||!isYSeq(l.Text) {break}
