 return true
}
func allTags(sheets []*Sheet) []string {seen:=map[string]bool{};for _,s:=range sheets {for _,t:=range s.Tags {seen[t]=true}};ss:=[]string{};for t:=range seen{ss=append(ss,t)};sort.Strings(ss);return ss}
func listTable(sheets []*Sheet,brief bool) string {
 ss:=append([]*Sheet{},sheets...);sort.SliceStable(ss,func(i,j int)bool{return ss[i].Title<ss[j].Title})
 titleWidth:=6;fileWidth:=5
 for _,s:=range ss {if n:=utf8.RuneCountInString(s.Title);n>titleWidth{titleWidth=n};if n:=utf8.RuneCountInString(s.File);n>fileWidth{fileWidth=n}}
 var b strings.Builder
 if brief {fmt.Fprintf(&b,"%-*s %s\n",titleWidth,"title:","tags:")}else{fmt.Fprintf(&b,"%-*s %-*s %s\n",titleWidth,"title:",fileWidth,"file:","tags:")}
 for _,s:=range ss {
  if brief {fmt.Fprintf(&b,"%-*s %s\n",titleWidth,s.Title,strings.Join(s.Tags,","))} else {fmt.Fprintf(&b,"%-*s %-*s %s\n",titleWidth,s.Title,fileWidth,s.File,strings.Join(s.Tags,","))}
 }
 return b.String()
}
func directoriesText(paths []CheatPath) string {
 maxWidth:=0;for _,p:=range paths{if n:=utf8.RuneCountInString(p.Name)+1;n>maxWidth{maxWidth=n}}
 var b strings.Builder;for _,p:=range paths{fmt.Fprintf(&b,"%-*s %s\n",maxWidth,p.Name+":",p.Path)};return b.String()
}
func validateName(name string) error {
 if name=="" {return fmt.Errorf("cheatsheet name cannot be empty")}
 if filepath.IsAbs(name) {return fmt.Errorf("cheatsheet name cannot be an absolute path")}
 if strings.Contains(name,"..") {return fmt.Errorf("cheatsheet name cannot contain '..'")}
 if strings.HasPrefix(filepath.Base(name),".") {return fmt.Errorf("cheatsheet name cannot start with '.' (hidden files are not supported)")}
 return nil
}
