}
func installConfig(path string) int {
 reader:=bufio.NewReader(os.Stdin)
 yes,err:=prompt(reader,"A config file was not found. Would you like to create one now? [Y/n]: ")
 if err!=nil {return failure("failed to create config: "+err.Error())};if !yes{return 0}
 community,err:=prompt(reader,"Would you like to download the community cheatsheets? [Y/n]: ")
 if err!=nil {return failure("failed to run installer: failed to prompt: "+err.Error())}
 if community {return failure("failed to run installer: failed to download community cheatsheets: network access unavailable")}
 if err:=os.MkdirAll(filepath.Dir(path),0755);err!=nil {return failure("failed to run installer: "+err.Error())}
 for _,dir:=range []string{"personal","work"} {if err:=os.MkdirAll(filepath.Join(filepath.Dir(path),"cheatsheets",dir),0755);err!=nil{return failure("failed to run installer: "+err.Error())}}
 if err:=os.WriteFile(path,[]byte(initText(path)),0644);err!=nil{return failure("failed to run installer: "+err.Error())}
 fmt.Fprintf(os.Stdout,"Created config file: %s\nPlease read this file for advanced configuration information.\n",path)
