 "path/filepath"
 "sort"
 "strings"
 "unicode/utf8"
)

type Sheet struct {Title string; File string; Parent CheatPath; Tags []string; Syntax string; Text string; Raw []byte}
func readSheet(file,title string,parent CheatPath) (*Sheet,error) {
 raw,err:=os.ReadFile(file);if err!=nil {return nil,fmt.Errorf("failed to read file: %s, %w",file,err)}
 s:=&Sheet{Title:title,File:file,Parent:parent,Syntax:"bash",Text:string(raw),Raw:raw,Tags:append([]string{},parent.Tags...)}
 text:=s.Text
 if strings.HasPrefix(text,"---\n")||strings.HasPrefix(text,"---\r\n") {
  first:=strings.IndexByte(text,'\n')+1
  pos:=first;end:=-1;after:=-1
  for pos<=len(text) {
   e:=strings.IndexByte(text[pos:],'\n');if e<0{e=len(text)}else{e+=pos}
   if strings.TrimSuffix(text[pos:e],"\r")=="---" {end=pos;after=e;if after<len(text){after++};break}
   if e==len(text){break};pos=e+1
  }
  if end<0 {return nil,fmt.Errorf("failed to parse front-matter: failed to delimit frontmatter")}
  n,err:=parseYAML(text[first:end]);if err!=nil {return nil,fmt.Errorf("failed to parse front-matter: failed to unmarshal frontmatter: %w",err)}
  errs:=[]string{}
  if n.Kind!="map"&&n.Kind!="null" {errs=append(errs,yTypeError(n,"sheet.frontmatter"))}else{
   for _,p:=range n.Pairs {switch p.Key {case "tags":s.Tags=append(s.Tags,yStrings(p.Value,&errs)...);case "syntax":s.Syntax=yString(p.Value,&errs)}}
  }
  if err:=yUnmarshalErrors(errs);err!=nil{return nil,fmt.Errorf("failed to parse front-matter: failed to unmarshal frontmatter: %w",err)}
  s.Text=text[after:]
 }
 sort.Strings(s.Tags)
 return s,nil
}
func loadSheets(paths []CheatPath) ([]*Sheet,error) {
 sheets:=[]*Sheet{}
 for _,cp:=range paths {
  err:=filepath.WalkDir(cp.Path,func(path string,d fs.DirEntry,walkerr error) error {
   if walkerr!=nil {return walkerr}
   if d.IsDir() {if d.Name()==".git" {return filepath.SkipDir};return nil}
   if filepath.Ext(d.Name())!="" {return nil}
   title,_:=filepath.Rel(cp.Path,path);if title=="." {title=""}
   s,err:=readSheet(path,title,cp);if err!=nil {return fmt.Errorf("failed to load sheet: %s, path: %s, err: %w",title,path,err)}
   sheets=append(sheets,s);return nil
  })
